using Fortress.Mobile.Core.Models;
using Device = Fortress.Mobile.Core.Models.Device;
namespace Fortress.Mobile.Core.Mappers
{
    public class DeviceMapper
    {
        private static readonly byte[] GenericBytes = GetIconBytes(GenericImg);
        private static readonly byte[] AndroidBytes = GetIconBytes(AndroidImg);
        private static readonly byte[] AppleBytes = GetIconBytes(AppleImg);
        private static readonly byte[] HalberdBytes = GetIconBytes(BlueLogoImg);
        private static readonly byte[] SmartcardBytes = GetIconBytes(SmartcardImg);
        public static DeviceDto Map(Device device)
        {
            return new DeviceDto
            {
                Id = device.Id,
                DeviceType = device.DeviceType,
                MacAddress = device.MacAddress,
                SerialNumber = device.SerialNumber,                 
                IconUri= GetIcon(device.DeviceType)
            };
        }

        public static IEnumerable<DeviceDto> Map(IEnumerable<Device> devices)
        {
            return devices.Select(Map);
        }

        public static IEnumerable<Device> Map(IEnumerable<DeviceDto> deviceDtos)
        {
            return deviceDtos.Select(Map);
        }

        public static Device Map(DeviceDto deviceDto)
        {
            return new Device
            {
                Id = deviceDto.Id,
                DeviceType = deviceDto.DeviceType,
                MacAddress = deviceDto.MacAddress,
                SerialNumber = deviceDto.SerialNumber,
                Pin = deviceDto.Pin

            };
        }
        private static string GetIcon(string deviceType)
        {
            if (deviceType == "Halberd")
                return "gklogoblue64.png";
            if (deviceType == "Android")
                return "AndroidLogo.png";
            if (deviceType == "IPhone")
                return "AppleLogo.png";
            if (deviceType == "SmartCard")
                return "SmartCardLogo.png";

            return "gklogoblue64.png";

        }
        private static byte[] GetIconBytes(string img)
        {
            byte[] bytes = System.Convert.FromBase64String(img);
            return bytes;
        }

        private const string BlueLogoImg = "";
        private const string GenericImg = "";
        private const string SmartcardImg = "";
        private const string AndroidImg = "";
        private const string AppleImg = "";

    }
}

